-- lane: ARGS-RULED
--
-- chair-step: it UPDATEs platform.client_callable_door.argument_rules on 109 rows, MERGING per
--   argument so nothing another lane declared is thrown away. No body changes. Inverse:
--   migrations/inverse/argsruled_the_last_hundred_and_nine_down.sql.
--
-- ARGS-RULED — THE LAST 109 DOORS AND THEIR 267 ID ARGUMENTS. THE CENSUS REACHES ZERO.
--
-- 136 of the 267 are decided by a LADDER PRIMITIVE this body calls, at the argument position that
-- primitive uses for that kind of id: `custom.assert_client_may_open/_may_change` (arg2 = the
-- record, arg1 = the organization), `custom.assert_may_know_table` (arg2 = the Table),
-- `custom.assert_client_may_reach` / `iam.has_org_access` (the organization),
-- `custom.has_visibility` (arg3), `custom.effective_level` (arg3), `iam.has_access` (arg2),
-- `iam.may_address_user_in_org` (arg1 = the person). `custom.assert_store_door` and
-- `platform.assert_relations_door` are NOT on that list — they decide a PRODUCT SWITCH and the
-- store-owner role and no membership — so no argument was cleared by one of those.
--
-- THE OTHER 131 WERE READ ONE AT A TIME, and they came out in five shapes. Each row says which:
--
--   DERIVED BY ORGANIZATION (the largest) — the argument reaches no table predicate without
--   `organization_id = p_organization_id` beside it, and that organization is decided on the
--   ladder in the same body. It can name nothing outside the organization the caller was
--   admitted to, and a row of another one answers exactly what an invented id answers. This is a
--   claim a guard can check by reading the body, which is what the brief asked for.
--
--   A FILTER — `p_x is null or <column> = p_x` over a set the caller is already entitled to read.
--   It narrows; it cannot widen, and it cannot name a row outside the set.
--
--   DERIVED, BY A CALLEE — handed to a door that decides it (`custom.io_export`,
--   `custom.form_declare`, `custom.query_can_see`, `custom.record_write`, `custom.read_record`,
--   `custom._display_of_field`, `custom.portal_principal_bind`, `custom._checklist_instantiate`),
--   with nothing read before the call.
--
--   CHECKED BY NAME, where the check is not a ladder call: a membership lookup
--   (`custom.work_person`, `custom.work_approval_request`, `custom.share_grant`), an identity
--   compared to the caller (`custom.doc_sign`, `custom.portal_principal_bind`), an organization
--   compared to a derived one (`custom.io_comment_write`, `public.hr_wf_request`).
--
--   CANNOT CONFER ACCESS, WITH THE REASON — and only where that is demonstrably true:
--   `custom.record_write_many(p_ids)` mints identities for NEW rows and a collision is refused by
--   the primary key `(organization_id, id)` rather than overwriting;
--   `public.saved_view_save(p_subject_id)` appears only inside statements already narrowed to
--   `created_by = auth.uid()`; `custom.provenance_write(p_conversation_id)` and
--   `custom.work_approval_request(p_conversation_id)` are pointers never read back.
--
-- ONE ARGUMENT IS RULED "ALREADY RIGHT" AFTER A SUSPICION: `custom.comment_write(p_mentions)`.
-- Every mention goes through `custom.history_people(organization, ids)` AND
-- `custom.has_visibility(that person, 'record', record, 'viewer')` before the comment is written.
-- Nothing to fix; it is declared as it stands.

set lock_timeout = '4s';

update platform.client_callable_door d
   set argument_rules = jsonb_set(
         coalesce(d.argument_rules, '{}'::jsonb) || '{"version": 1, "declared_by": "argsruled_the_last_hundred_and_nine.sql", "declared_at": "2026-09-21 lane ARGS-RULED, per-door reading of the body"}'::jsonb, '{arguments}',
         coalesce(d.argument_rules -> 'arguments', '{}'::jsonb)
           || (select jsonb_object_agg(t.k, coalesce(d.argument_rules -> 'arguments' -> t.k, '{}'::jsonb) || t.v)
                 from jsonb_each('{"p_organization": {"type": "uuid", "entity": "organization", "check": "this body decides it with custom.assert_client_may_reach(arg1), custom.assert_may_know_table(arg1), iam.has_org_access(arg1) \u2014 the organization wall \u2014 a non-member is refused before anything is read.", "foreign": {"sqlstate": "42501", "same_as_invented": true}, "verified": "2026-09-21 lane ARGS-RULED \u2014 read from this body"}, "p_table": {"type": "uuid", "entity": "custom_record", "check": "this body decides it with custom.assert_may_know_table(arg2) \u2014 the Table''s own ladder \u2014 you know a Table if you may open it or if anything in it has been shared with you.", "foreign": {"sqlstate": "42501", "same_as_invented": true}, "verified": "2026-09-21 lane ARGS-RULED \u2014 read from this body"}, "p_conversation": {"type": "uuid", "check": "A FILTER over custom.agent_table_origin (`o.conversation_id = p_conversation`) that decides only whether THIS table \u2014 already put through the Table ladder in this body \u2014 is exempt from the organization''s agent-approval knob. It reads nothing about the conversation and returns nothing about it.", "foreign": {"not_a_leak": true, "same_as_invented": true, "note": "the un-exempt, stricter answer"}, "verified": "2026-09-21 lane ARGS-RULED \u2014 read from this body"}}'::jsonb) as t(k, v)), true)
 where d.schema_name = 'custom' and d.function_name = 'agent_change_approval';

